    15	  class TokenizerBasic : public Tokenizer
    16	  {
    17	  public:
    18	    bool advance();
    19	  };
    20	
    21	  bool TokenizerBasic::advance() {
    22	    word_begin = word_end;
    23	    begin_pos = end_pos;
    24	    FilterChar * cur = word_begin;
    25	    unsigned int cur_pos = begin_pos;
    26	    word.clear();
    27	
    28	    // skip spaces (non-word characters)
    29	    while (*cur != 0 &&
    30	           !(is_word(*cur)
    31	             || (is_begin(*cur) && is_word(cur[1])))) 
    32	    {
    33	      cur_pos += cur->width;
    34	      ++cur;
    35	    }
    36	
    37	    if (*cur == 0) return false;
    38	
    39	    word_begin = cur;
    40	    begin_pos = cur_pos;
    41	
    42	    if (is_begin(*cur) && is_word(cur[1]))
    43	    {
    44	      cur_pos += cur->width;
    45	      ++cur;
    46	    }
    47	
    48	    while (is_word(*cur) || 
    49	           (is_middle(*cur) && 
    50	            cur > word_begin && is_word(cur[-1]) &&
    51	            is_word(cur[1]) )) 
    52	    {
    53	      word.append(*cur);
    54	      cur_pos += cur->width;
    55	      ++cur;
    56	    }
    57	
    58	    if (is_end(*cur))
    59	    {
    60	      word.append(*cur);
    61	      cur_pos += cur->width;
    62	      ++cur;
    63	    }
    64	
    65	    word.append('\0');
    66	    word_end = cur;
    67	    end_pos = cur_pos;
    68	
    69	    return true;
    70	  }
